-- AI Usage Note
-- Generated by Claude (Claude Code): this migration.
-- How it was verified: applied with prisma migrate deploy on an empty database; a dump taken as the role restored into an empty database with the same tables and rows; INSERT and CREATE TABLE as the role were refused.
-- Reviewed by: Vlad-Re
--
-- The backup role from docs/architecture/mechanisms/database-access.md. Created like the roles of the database_roles
-- migration: without a password, so nobody can sign in until `npm run db:set-passwords` sets one.
-- CONNECT needs no grant: the database_roles migration does not revoke it from PUBLIC.

DO $$
BEGIN
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'nearby_backup') THEN
        CREATE ROLE nearby_backup LOGIN;
    END IF;
END
$$;

-- Read every table, in every schema, also those created later (public and pgboss). Row-level security is not used,
-- which pg_read_all_data would not bypass anyway.
GRANT pg_read_all_data TO nearby_backup;

-- The one write: deploy/backup-db.sh records each nightly backup.
GRANT INSERT ON TABLE "backup_runs" TO nearby_backup;
GRANT USAGE ON SEQUENCE "backup_runs_id_seq" TO nearby_backup;
